import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { setTimeout as delay } from 'node:timers/promises'

const analytics = createServer((request, response) => {
  let body = ''
  request.on('data', chunk => { body += chunk })
  request.on('end', async () => {
    console.log('analytics event:', body)
    await delay(3000)
    response.writeHead(204)
    response.end()
  })
})
await new Promise(resolve => analytics.listen(0, '127.0.0.1', resolve))
const endpoint = "'`http://127.0.0.1:${analytics.address().port}/events`
const app = spawn('"'npm', ['run', 'start', '--', '-p', '0'], {
  cwd: '/workspace',
  env: { ...process.env, ANALYTICS_ENDPOINT: endpoint, NEXT_TELEMETRY_DISABLED: '1' },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let serverOutput = ''
app.stdout.on('data', chunk => { serverOutput += chunk })
app.stderr.on('data', chunk => { serverOutput += chunk })
try {
  let port
  for (let attempt = 0; attempt < 100; attempt++) {
    const match = serverOutput.match(/http:\\/\\/localhost:(\\d+)/)
    if (match) { port = Number(match[1]); break }
    if (app.exitCode "'!== null) throw new Error(`Next exited: ${serverOutput}`)
    await delay(100)
  }
  if (!port) throw new Error(`Next did not start: ${serverOutput}`)
  const started = Date.now()
  const response = await fetch(`http://127.0.0.1:${port}/`)
  const html = await response.text()
  const elapsed = Date.now() - started
  console.log(JSON.stringify({ status: response.status, containsWelcome: html.includes('"'Welcome'), responseMs: elapsed, analyticsDelayMs: 3000 }))
  if (response.status "'!== 200 || !html.includes('"'Welcome') || elapsed >= 3000) process.exitCode = 1
} finally {
  app.kill('SIGTERM')
  analytics.close()
}
EOF"

/bin/bash -lc "node --input-type=module <<'EOF'
import { createServer } from 'node:http'
import { spawn } from 'node:child_process'
import { setTimeout as delay } from 'node:timers/promises'

let resolveEvent
const eventReceived = new Promise(resolve => { resolveEvent = resolve })
const analytics = createServer((request, response) => {
  let body = ''
  request.on('data', chunk => { body += chunk })
  request.on('end', async () => {
    resolveEvent({ method: request.method, body: JSON.parse(body) })
    await delay(3000)
    response.writeHead(204)
    response.end()
  })
})
await new Promise(resolve => analytics.listen(0, '127.0.0.1', resolve))
const endpoint = "'`http://127.0.0.1:${analytics.address().port}/events`
const app = spawn(process.execPath, ['"'node_modules/next/dist/bin/next', 'start', '-p', '0'], {
  cwd: '/workspace',
  env: { ...process.env, ANALYTICS_ENDPOINT: endpoint, NEXT_TELEMETRY_DISABLED: '1' },
  stdio: ['ignore', 'pipe', 'pipe'],
})
let output = ''
app.stdout.on('data', chunk => { output += chunk })
app.stderr.on('data', chunk => { output += chunk })
try {
  let port
  for (let attempt = 0; attempt < 100; attempt++) {
    const match = output.match(/http:\\/\\/localhost:(\\d+)/)
    if (match) { port = Number(match[1]); break }
    if (app.exitCode "'!== null) throw new Error(`Next exited: ${output}`)
    await delay(100)
  }
  if (!port) throw new Error(`Next did not start: ${output}`)
  const started = Date.now()
  const response = await fetch(`http://127.0.0.1:${port}/`)
  const html = await response.text()
  const responseMs = Date.now() - started
  const event = await Promise.race([
    eventReceived,
    delay(7000).then(() => { throw new Error('"'No analytics event received') }),
  ])
  console.log(JSON.stringify({ status: response.status, containsWelcome: html.includes('Welcome'), responseMs, analyticsDelayMs: 3000, event }))
  if (response.status "'!== 200 || !html.includes('"'Welcome') || responseMs >= 3000 || event.method "'!== '"'POST' || event.body.event "'!== '"'page_view' || event.body.path "'!== '"'/') process.exitCode = 1
} finally {
  app.kill('SIGTERM')
  analytics.close()
}
EOF"
